# V126: iniciar/recuperar Chromium ANTES de marcar la cola en ejecución.
# Había otro preflight que podía terminar la sesión antes de entrar al
# supervisor V125, dejando 0 intentos y 10 pendientes.
if not _puerto_chrome_activo():
    try:
        _asegurar_chromium_controlable()
        limite = time.time() + 15
        while time.time() < limite and not _puerto_chrome_activo():
            time.sleep(0.5)
    except Exception as exc:
        messagebox.showerror("Publicación detenida", f"No pude iniciar Chromium automáticamente.\n\n{exc}")
        return
if not _puerto_chrome_activo():
    messagebox.showerror("Publicación detenida", "Chromium se abrió, pero el puerto 9222 no respondió. Cierra únicamente el Chromium del bot y vuelve a intentarlo.")
    return

cola_en_ejecucion = True
